package techguns.gametest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.fluids.*;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.machines.*;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class ReactionGameTests {
    private static ProcessingMachine chamber(GameTestHelper h){h.setBlock(2,1,1,TGMachines.BLOCKS.get(MachineKind.REACTION).get());var m=(ProcessingMachine)h.getBlockEntity(new BlockPos(2,1,1));for(var entry:m.structureParts(Direction.SOUTH).entrySet())h.getLevel().setBlockAndUpdate(entry.getKey(),(entry.getValue()?TGFabricator.REACTION_GLASS:TGFabricator.REACTION_HOUSING).get().defaultBlockState());h.assertTrue(m.formStructure(Direction.NORTH),"The original three-by-three-by-four chamber must form from its front face");return m;}
    private static void prepare(GameTestHelper h,ProcessingMachine m,String id){var r=ReactionRecipe.byId(id);var values=r.input().getItems();h.assertTrue(values.length>0,"Standalone reaction ingredient must resolve: "+id);m.inventory.setStackInSlot(0,values[0].copyWithCount(1));m.inventory.setStackInSlot(1,new ItemStack(r.focus()));m.reactor.intensity=r.preferredIntensity();m.inputTank.fill(new FluidStack(r.fluid(),r.liquidLevel()*1000),FluidAction.EXECUTE);m.setEnergy(1000000);}
    @GameTest(template="empty") public static void sourceReactionsCompleteByFollowingLiveRequiredIntensity(GameTestHelper h){var m=chamber(h);prepare(h,m,"RC_UV_WHEAT");m.tick();h.assertTrue(m.reactor.running()&&m.totalTime==600,"Wheat reaction starts with ten sixty-tick reaction windows");for(int window=0;window<5;window++){m.reactor.intensity=m.reactor.requiredIntensity;for(int i=0;i<60;i++)m.tick();}
        h.assertTrue(!m.reactor.running()&&m.inventory.getStackInSlot(2).is(Items.WHEAT)&&m.inventory.getStackInSlot(3).is(Items.WHEAT_SEEDS)&&m.inventory.getStackInSlot(3).getCount()==2,"Five successful live adjustments produce original wheat and seed outputs");h.assertTrue(m.energy.getEnergyStored()==750000&&m.inputTank.isEmpty(),"The reaction charges 50000 FE per successful reaction window and consumes one bucket on completion");h.assertTrue(m.inventory.getStackInSlot(1).is(TGItems.RC_UV_EMITTER.get()),"The focus is retained");h.succeed();}
    @GameTest(template="empty") public static void removingFocusFailsReactionAndConsumesNoOutputMaterials(GameTestHelper h){var m=chamber(h);prepare(h,m,"RC_BLAZEROD");m.tick();m.inventory.setStackInSlot(1,ItemStack.EMPTY);for(int i=0;i<60;i++)m.tick();h.assertTrue(!m.reactor.running()&&m.formed&&m.inventory.getStackInSlot(0).isEmpty()&&m.inventory.getStackInSlot(2).isEmpty(),"Removing the heat focus aborts the source BREAK_ITEM reaction and destroys the reserved input");h.assertTrue(m.inputTank.getFluidAmount()==4000&&m.energy.getEnergyStored()==750000,"A failed reaction retains its fluid and still charges the attempted source energy pulse");h.succeed();}
    @GameTest(template="empty") public static void fluidLimitCapsAutomationFillAndPortsNeverDrain(GameTestHelper h){var m=chamber(h);var fluids=m.getCapability(ForgeCapabilities.FLUID_HANDLER).orElseThrow(IllegalStateException::new);h.assertTrue(fluids.fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,5000),FluidAction.EXECUTE)==5000,"Without a limit the chamber takes fluid freely");m.inputTank.setFluid(FluidStack.EMPTY);m.button(20+30);h.assertTrue(m.fluidLimit==3000&&fluids.fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,5000),FluidAction.EXECUTE)==3000,"The fluid limit caps the tank at three buckets");h.assertTrue(fluids.drain(5000,FluidAction.EXECUTE).isEmpty(),"Automation cannot drain the reaction chamber");m.button(13);h.assertTrue(m.reactor.intensity==4,"Clicking a pip selects that intensity directly");h.succeed();}
    @GameTest(template="empty") public static void reactionSaveRetainsLiveRequirementAndWindowCountdown(GameTestHelper h){var m=chamber(h);prepare(h,m,"RC_UV_WHEAT");m.tick();for(int i=0;i<37;i++)m.tick();var copy=new ProcessingMachine(m.getBlockPos(),m.getBlockState());copy.setLevel(h.getLevel());copy.load(m.saveWithoutMetadata());h.assertTrue(copy.reactor.running()&&copy.progress==37&&copy.reactor.nextTick==23&&copy.reactor.requiredIntensity==3,"Persistence retains the exact point within the sixty-tick reaction window");for(int i=37;i<300;i++){copy.reactor.intensity=copy.reactor.requiredIntensity;copy.tick();}h.assertTrue(copy.inventory.getStackInSlot(2).is(Items.WHEAT)&&copy.energy.getEnergyStored()==750000,"Reload resumes the original reaction and produces its result once");h.succeed();}
    @GameTest(template="empty") public static void chamberConnectorsExposeOnlyTheirSourceCapabilities(GameTestHelper h){var m=chamber(h);h.assertTrue(m.structureParts(Direction.SOUTH).size()==35,"Source chamber uses eighteen glass blocks and seventeen housings around the controller");var center=m.getBlockPos().relative(Direction.SOUTH);var top=(MachinePartEntity)h.getLevel().getBlockEntity(center.above(3));var side=(MachinePartEntity)h.getLevel().getBlockEntity(center.relative(Direction.SOUTH));var glass=(MachinePartEntity)h.getLevel().getBlockEntity(center.above());h.assertTrue(top.getCapability(ForgeCapabilities.ENERGY).isPresent()&&!top.getCapability(ForgeCapabilities.ITEM_HANDLER).isPresent(),"Top connector accepts energy only");h.assertTrue(side.getCapability(ForgeCapabilities.ITEM_HANDLER).isPresent()&&side.getCapability(ForgeCapabilities.FLUID_HANDLER).isPresent()&&!side.getCapability(ForgeCapabilities.ENERGY).isPresent(),"Base side connectors expose items and fluids");h.assertTrue(!glass.getCapability(ForgeCapabilities.ENERGY).isPresent()&&!glass.getCapability(ForgeCapabilities.FLUID_HANDLER).isPresent(),"Ordinary glass is not an automation port");h.succeed();}
    @GameTest(template="empty") public static void allSevenSourceReactionSettingsAndStandaloneFluidFallbacksRemainAvailable(GameTestHelper h){h.assertTrue(ReactionRecipe.all().size()>=7,"All source reaction descriptions are retained");var laser=ReactionRecipe.byId("RC_LASER_FOCUS");h.assertTrue(laser.energy()==100000&&laser.liquidLevel()==4&&laser.liquidConsumption()==4000&&laser.requiredCompletion()==5,"Laser focus keeps its source thresholds and energy");h.assertTrue(laser.fluid()==ReactionRecipe.externalOrLava("redstone")&&ReactionRecipe.byId("RC_ANTIGRAV").fluid()==ReactionRecipe.externalOrLava("ender"),"Original standalone fallback uses lava when the integration fluids are absent");h.succeed();}
}
